@push('scripts')<script>$(function(){$('.js-cancel').on('click',function(){const button=$(this);Swal.fire({icon:'warning',title:'ยกเลิกใบรับคืน?',input:'textarea',inputLabel:'เหตุผลการยกเลิก',inputPlaceholder:'ระบุเหตุผลอย่างน้อย 5 ตัวอักษร',showCancelButton:true,confirmButtonText:'ยืนยันยกเลิก',cancelButtonText:'กลับ',confirmButtonColor:'#dc3545',inputValidator:value=>!value||value.trim().length<5?'กรุณาระบุเหตุผลอย่างน้อย 5 ตัวอักษร':undefined}).then(result=>{if(!result.isConfirmed)return;button.prop('disabled',true);$.post(button.data('url'),{_token:$('meta[name=csrf-token]').attr('content'),reason:result.value}).done(response=>Swal.fire({icon:'success',text:response.msg,timer:1200,showConfirmButton:false}).then(()=>{window.location.href=response.redirect;})).fail(xhr=>{button.prop('disabled',false);Swal.fire({icon:'error',text:xhr.responseJSON?.message||'ยกเลิกใบรับคืนไม่สำเร็จ'});});});});$('.js-reverse').on('click',function(){const button=$(this);Swal.fire({icon:'warning',title:'ยกเลิกรายการรับคืน?',input:'textarea',inputLabel:'เหตุผลการยกเลิกรายการรับคืน',inputPlaceholder:'ระบุเหตุผลอย่างน้อย 10 ตัวอักษร',showCancelButton:true,confirmButtonText:'ยืนยันยกเลิกรายการรับคืน',cancelButtonText:'กลับ',confirmButtonColor:'#dc3545',inputValidator:value=>!value||value.trim().length<10?'กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษร':undefined}).then(result=>{if(!result.isConfirmed)return;button.prop('disabled',true);$.post(button.data('url'),{_token:$('meta[name=csrf-token]').attr('content'),reason:result.value}).done(response=>Swal.fire({icon:'success',text:response.msg,timer:1200,showConfirmButton:false}).then(()=>{window.location.href=response.redirect;})).fail(xhr=>{button.prop('disabled',false);Swal.fire({icon:'error',text:xhr.responseJSON?.message||'ยกเลิกรายการรับคืนไม่สำเร็จ'});});});});});</script>@endpush
@push('scripts')<script>$(function(){$('.js-act').on('click',function(){const a=$(this).data('action');Swal.fire({icon:'warning',title:a==='approve'?'อนุมัติใบรับคืน?':'ลง Stock ใบรับคืน?',showCancelButton:true,confirmButtonText:'ยืนยัน',cancelButtonText:'ยกเลิก'}).then(x=>{if(!x.isConfirmed)return;$.post('{{ route('wms.issue-returns.show',$document) }}/'+a,{_token:$('meta[name=csrf-token]').attr('content')}).done(()=>location.reload()).fail(e=>Swal.fire({icon:'error',text:e.responseJSON?.message||'ดำเนินการไม่สำเร็จ'}));});});});</script>@endpush
